<?php

declare(strict_types=1);

namespace Myracloud\WebApi\V1;

use Myracloud\WebApi\Contract;
use Myracloud\WebApi\Http\Transport;
use Myracloud\WebApi\Model\DomainName;
use Myracloud\WebApi\Model\Maintenance;
use Myracloud\WebApi\Model\Page;
use Myracloud\WebApi\Model\Persisted;

/**
 * `/{lang}/rapi/maintenance/{subdomain}`: GET `/{page}` lists, PUT creates, POST updates,
 * DELETE deletes (body: id, fqdn — as the manual says). `active` is generated by Myra.
 */
final readonly class Maintenances implements Contract\Maintenances
{
    /**
     * @internal built by {@see Client}
     */
    public function __construct(private Transport $transport) {}

    public function list(string $subdomain): array
    {
        return Page::collect(fn(int $page): Page => $this->page($subdomain, $page));
    }

    public function page(string $subdomain, int $page): Page
    {
        return Page::fromJson($this->transport->send('GET', self::path($subdomain) . '/' . Page::number($page)), 'list', Maintenance::fromJson(...));
    }

    public function create(Maintenance $maintenance): Maintenance
    {
        Persisted::assertNew($maintenance->id(), 'maintenance');

        return Maintenance::fromJson($this->transport->send('PUT', self::path($maintenance->subdomain()), body: $maintenance->toJson(false))->first('targetObject'));
    }

    public function update(Maintenance $maintenance): Maintenance
    {
        Persisted::versionOf($maintenance->id(), $maintenance->modified(), 'maintenance');

        return Maintenance::fromJson($this->transport->send('POST', self::path($maintenance->subdomain()), body: $maintenance->toJson(false))->first('targetObject'));
    }

    public function delete(Maintenance $maintenance): void
    {
        [$id] = Persisted::versionOf($maintenance->id(), $maintenance->modified(), 'maintenance');
        $this->transport->send('DELETE', self::path($maintenance->subdomain()), body: ['id' => $id, 'fqdn' => $maintenance->subdomain()]);
    }

    private static function path(string $subdomain): string
    {
        return 'maintenance/' . rawurlencode(DomainName::normalize($subdomain));
    }
}
